/**
 * Test flow for Created or Updated trigger
 * Tests: Record creation or update trigger with changed fields tracking
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testCreatedOrUpdatedTrigger = Flow(
    {
        $id: Now.ID['test_created_or_updated_trigger_flow'],
        name: 'Test Created or Updated Trigger',
        description: 'Tests the Created or Updated trigger with all parameters',
    },
    wfa.trigger(
        trigger.record.createdOrUpdated,
        { $id: Now.ID['test_created_or_updated_trigger'] },
        {
            table: 'incident',
            condition: 'priority<=2',
            run_on_extended: 'false',
            run_when_setting: 'both',
            run_flow_in: 'background',
            run_when_user_setting: 'any',
            run_when_user_list: [],
            trigger_strategy: 'unique_changes',
        }
    ),
    (_params) => {
        // Log all trigger outputs including nested reference fields
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_created_or_updated_log'] },
            {
                log_level: 'info',
                log_message: `Created/Updated Trigger - Current: ${wfa.dataPill(_params.trigger.current, 'reference')}, Table: ${wfa.dataPill(_params.trigger.table_name, 'table_name')}, Changed Fields: ${wfa.dataPill(_params.trigger.changed_fields, 'array.object')}, Start Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}, Assignment Group: ${wfa.dataPill(_params.trigger.current.assignment_group, 'reference')}, Assignment Group Name: ${wfa.dataPill(_params.trigger.current.assignment_group.name, 'string')}`,
            }
        )
    }
)

// Flow 2 with only mandatory inputs and other variations

export const testCreatedOrUpdatedTriggerOnlyMandatory = Flow(
    {
        $id: Now.ID['test_created_or_updated_trigger_mandatory_flow'],
        name: 'Test Created or Updated Trigger - Mandatory',
        description: 'Tests the Created or Updated trigger with mandatory inputs and other variations',
    },
    wfa.trigger(
        trigger.record.createdOrUpdated,
        { $id: Now.ID['test_created_or_updated_trigger_mandatory'] },
        {
            table: 'incident',
            run_on_extended: 'true',
            run_when_setting: 'non_interactive',
            run_flow_in: 'foreground',
            run_when_user_setting: 'one_of',
            trigger_strategy: 'always',
            run_when_user_list: ['62826bf03710200044e0bfc8bcbe5df1'],
        }
    ),
    (_params) => {
        // Log all trigger outputs including nested reference fields
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_created_or_updated_trigger_mandatory_log'] },
            {
                log_level: 'info',
                log_message: `Created/Updated Trigger (Mandatory) - Current: ${wfa.dataPill(_params.trigger.current, 'reference')}, Table: ${wfa.dataPill(_params.trigger.table_name, 'table_name')}, Changed Fields: ${wfa.dataPill(_params.trigger.changed_fields, 'array.object')}, Assignment Group: ${wfa.dataPill(_params.trigger.current.assignment_group, 'reference')}, Start Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)
